-- An invitation ends once, and the consume policies admit only an unended one
-- (ADR-0083 §3 as amended at `D35.3`). Generated by drizzle-kit from
-- `src/schema/organizations.ts`; the only edits are this comment and the
-- `NOT VALID` on the constraint.
--
-- The invitee's and the bearer's consume policies gain "no stamp yet" in
-- their `USING`, so a transaction that holds an invitee's principal or a
-- bearer's hash cannot touch an invitation that has ended — never clear the
-- `revoked_at` an organization's admin wrote, never stamp a declined one
-- accepted. Reads are unaffected: the two select policies are unchanged.
-- Expiry stays out of the policy; it is read against the application's
-- clock (`pendingAt`), and a `now()` here would be a second clock.
--
-- `organization_invitations_one_terminal_stamp` holds at most one of the
-- three stamps. The only write of a stamp is the repository's consume, which
-- sets one on a row carrying none, so no row this repository wrote violates
-- it.
--
-- **Blocking, briefly** (ADR-0060 §5 as carried by ADR-0078). `ALTER POLICY`
-- and `ADD CONSTRAINT … NOT VALID` take an `ACCESS EXCLUSIVE` lock on
-- `organization_invitations`, but both are catalogue changes that read no
-- rows, so the lock lasts as long as the bookkeeping. The constraint binds
-- every write from here on; the scan of the existing rows is `0023`'s
-- `VALIDATE CONSTRAINT`, in the second lane, under a lock that lets reads and
-- writes through.
--
-- **Deploy order**: either. No release writes two stamps, and no release's
-- consume touches an ended invitation.
ALTER TABLE "organization_invitations" ADD CONSTRAINT "organization_invitations_one_terminal_stamp" CHECK (num_nonnulls("organization_invitations"."accepted_at", "organization_invitations"."declined_at", "organization_invitations"."revoked_at") <= 1) NOT VALID;--> statement-breakpoint
ALTER POLICY "organization_invitations_invitee_consume" ON "organization_invitations" TO public USING ((email = (select u.email from users u where u.id = nullif(current_setting('app.user_id', true), '')::uuid and u.deleted_at is null)) and accepted_at is null and declined_at is null and revoked_at is null) WITH CHECK ((email = (select u.email from users u where u.id = nullif(current_setting('app.user_id', true), '')::uuid and u.deleted_at is null)) and revoked_at is null);--> statement-breakpoint
ALTER POLICY "organization_invitations_bearer_consume" ON "organization_invitations" TO public USING ((token_hash = nullif(current_setting('app.invitation_token_hash', true), '')) and accepted_at is null and declined_at is null and revoked_at is null) WITH CHECK ((token_hash = nullif(current_setting('app.invitation_token_hash', true), '')) and revoked_at is null and declined_at is null);